def clean(df):
    df = df.copy()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    df = df[(df['flipper_length_mm'] >= 0) & (2500 <= df['body_mass_g']) & (df['body_mass_g'] <= 6500)]
    df['sex'] = df['sex'].str.lower()
    return df

def answer(df):
    avg_body_mass = df.groupby('species')['body_mass_g'].mean().reset_index()
    result = dict(zip(avg_body_mass['species'], avg_body_mass['body_mass_g']))
    return result}
